#!/usr/bin/env python3
"""Copyright (C) 2026 NOS contributors. Generate the C registry, without native wire structs."""
import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def generate():
    r = json.loads((ROOT / "protocols/nlp/v1/registry.json").read_text())
    lines = [
        "/* Copyright (C) 2026 NOS contributors. Generated by scripts/gen_nlp_registry.py. */",
        "#ifndef NOS_NLP_REGISTRY_H",
        "#define NOS_NLP_REGISTRY_H",
        "#include <stdint.h>",
    ]
    for table, prefix in [
        ("core_opcodes", "NLP_OP_"),
        ("statuses", "NLP_"),
        ("control_tags", "NLP_TAG_"),
    ]:
        lines += [
            "#define " + prefix + name + " " + str(value) + ("" if table == "statuses" else "u")
            for name, value in r[table].items()
        ]
    for cap in r["capabilities"]:
        name = cap["name"].upper()
        raw = bytes.fromhex(cap["type_uuid"].replace("-", ""))
        lines += ["#define NLP_UUID_" + name + " {" + ",".join("0x%02x" % x for x in raw) + "}"]
        lines += [
            "#define NLP_" + name + "_" + op + " " + str(code) + "u"
            for op, code in cap["operations"].items()
        ]
    lines += ["#endif", ""]
    return "\n".join(lines)


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    path = ROOT / "include/nos/nlp/registry.h"
    expected = generate()
    if args.check:
        if not path.exists() or path.read_text() != expected:
            raise SystemExit("NLP registry header is stale")
    else:
        path.write_text(expected)
